import json
import time
import urllib.request
import urllib.error
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = 'http://localhost:8080'
token = None

def get_token():
    global token
    while True:
        try:
            req = urllib.request.Request(BASE + '/token', method='POST')
            with urllib.request.urlopen(req, timeout=30) as res:
                token = [REDACTED_SECRET]'token']
            return
        except urllib.error.HTTPError as e:
            if e.code == 429:
                delay = float(e.headers.get('Retry-After', '1'))
                time.sleep(max(delay, 0))
                continue
            if 500 <= e.code < 600:
                time.sleep(1)
                continue
            raise
        except (urllib.error.URLError, TimeoutError):
            time.sleep(1)

def request_json(path, auth=True):
    global token
    refreshed = False
    while True:
        headers = {'Accept': 'application/json'}
        if auth:
            if token is None:
                get_token()
            headers['Authorization'] = 'Bearer ' + token
        req = urllib.request.Request(BASE + path, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as res:
                return json.loads(res.read())
        except urllib.error.HTTPError as e:
            if auth and e.code in (401, 403) and not refreshed:
                token = None
                get_token()
                refreshed = True
                continue
            if e.code == 429:
                delay = e.headers.get('Retry-After')
                if delay is None:
                    body = e.read().decode(errors='replace')
                    try:
                        delay = json.loads(body).get('retry_after', '1')
                    except Exception:
                        delay = '1'
                time.sleep(max(float(delay), 0))
                continue
            if e.code in (408, 425) or 500 <= e.code < 600:
                time.sleep(1)
                continue
            raise
        except (urllib.error.URLError, TimeoutError):
            time.sleep(1)

# Fetch every page; page navigation is honored, with a page-number fallback.
orders = {}
duplicates = 0
page = 1
seen_pages = set()
while page:
    if page in seen_pages:
        raise RuntimeError(f'pagination loop at page {page}')
    seen_pages.add(page)
    data = request_json(f'/orders?page={page}')
    for order in data['items']:
        oid = order['id']
        if oid in orders:
            duplicates += 1
        else:
            orders[oid] = order
    nxt = data.get('next')
    if nxt:
        # Docs describe next as a path; parse its page parameter.
        from urllib.parse import urlparse, parse_qs
        qs = parse_qs(urlparse(nxt).query)
        if 'page' not in qs:
            raise RuntimeError(f'unexpected next path: {nxt"'!r}'"')
        page = int(qs['page'][0])
    else:
        page = None

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
customers = {}
by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
order_count = 0
for order in orders.values():
    if order['status'] "'!= '"'shipped':
        continue
    placed = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
    if not (start <= placed < end):
        continue
    cid = order['customer_id']
    if cid not in customers:
        customers[cid] = request_json(f'/customers/{cid}')
    customer = customers[cid]
    amount = int(order['amount_cents'])
    pct = int(customer['discount_pct'])
    discounted = int((Decimal(amount) * Decimal(100 - pct) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    by_region[customer['region']] += discounted
    order_count += 1

result = {
    'total_cents': sum(by_region.values()),
    'order_count': order_count,
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
with open('/workspace/result.json', 'w') as f:
    json.dump(result, f, indent=2)
    f.write('\\n')
print(json.dumps({'unique_orders': len(orders), 'pages': len(seen_pages), 'customers_cached': len(customers), 'result': result}, indent=2))
